cd /tmp && python3 - <<'E'
import re
def parse(p):
    d={}
    for l in open(p):
        m=re.match(r'(custom_components\S+)\s+\d+\s+\d+\s+\d+%\s+(.*)',l)
        if m:
            ls=[]
            for part in m.group(2).split(', '):
                a,_,b=part.partition('-'); ls+=range(int(a),int(b or a)+1)
            d[m.group(1)]=ls
    return d
H='/Users/raman/projects/lock_code_manager/.worktrees/credential-address-core/';B='/tmp/lcm-base/'
h=parse('/tmp/lcm-pr1/t9-cov.log');b=parse('/tmp/lcm-pr1/t9-base.log')
for f in sorted(set(h)|set(b)):
    hs=[open(H+f).read().split('\n')[i-1].strip() for i in h.get(f,[])]
    bs=[open(B+f).read().split('\n')[i-1].strip() for i in b.get(f,[])]
    if hs!=bs: print(f,'\nHEAD',hs,'\nBASE',bs)
print('compared')
E

